import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Check if we have enough patients and features
    if feats.n < 10 or len(feats.ids) < 2:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Compute t-scores for all features
    t_scores = []
    for i, fid in enumerate(feats.ids):
        y0 = feats.x[feats.y == 0, i]
        y1 = feats.x[feats.y == 1, i]
        if len(y0) > 0 and len(y1) > 0:
            t_stat, _ = stats.ttest_ind(y0, y1, equal_var=False)
            t_scores.append((abs(t_stat), fid))

    # Sort by absolute t-score descending
    t_scores.sort(reverse=True)

    # Select top features (limit to MAX_DRIVERS)
    selected_features = [fid for _, fid in t_scores[:MAX_DRIVERS]]

    # Build correlation pairs (only between selected features)
    corr_pairs = set()
    indices = [feats.column(fid) for fid in selected_features]
    if len(indices) > 1:
        corr_matrix = np.corrcoef(feats.x[:, indices].T)
        for i in range(len(selected_features)):
            for j in range(i+1, len(selected_features)):
                if abs(corr_matrix[i, j]) >= 0.6:
                    fid_i, fid_j = selected_features[i], selected_features[j]
                    corr_pairs.add((min(fid_i, fid_j), max(fid_i, fid_j)))

    # Return design with selected features
    return Design(
        drivers=(),
        columns=tuple(selected_features),
        products=tuple(corr_pairs),
        loadings={}
    )

